#include "client.h"
#define MIB (1024u*1024u)
int driveprobe(const Endpoint*ep,T letter,W*out,int cap){W selected[465],path[512],mapped[130],prefix[50],rg[33],route[100];U32 n=CNT(mapped);if(!letterok(letter)||!getmap(letter,selected,CNT(selected))||WNetGetConnectionW(letter,mapped,&n)||!route5(ep,route,CNT(route))){cp(out,cap,L"저장한 드라이브와 공유기 VPN 경로를 먼저 연결해야 합니다.");return 0;}
W*tail=selected,*last=0,*prev=0;while(*tail){if(*tail=='|'){prev=last;last=tail;}tail++;}if(!last||!prev)return 0;*last=0;*prev=0;Endpoint bind;if(!pair(selected,bind.host,bind.ip,bind.machine)||!eq(bind.host,ep->host)||!eq(bind.ip,ep->ip)||!eq(bind.machine,ep->machine)||!shareok(prev+1))return 0;_snwprintf(prefix,CNT(prefix),L"\\\\%ls\\",ep->ip);if(!cp(path,CNT(path),prefix)||!cat(path,CNT(path),prev+1)||!eq(path,mapped)||!guidtext(rg,CNT(rg)))return 0;cat(path,CNT(path),L"\\.cz5-test-");cat(path,CNT(path),rg);cat(path,CNT(path),L".tmp");const U32 size=256*MIB;U8*data=VirtualAlloc(0,size,0x3000,4),*readback=VirtualAlloc(0,MIB,0x3000,4);H f=BAD,r=BAD;int ok=0;U32 err=0;U64 wt=0,rt=0;if(!data||!readback){err=8;goto end;}if(BCryptGenRandom(0,data,size,2)){err=31;goto end;}
/* CREATE_NEW + delete-on-close: no existing user file can ever be replaced/deleted. */
f=CreateFileW(path,0xc0010000,7,0,1,0xac000100,0);if(f==BAD){err=GetLastError();goto end;}
U64 t=GetTickCount64();for(U32 i=0;i<size;i+=MIB){U32 got=0;if(!WriteFile(f,data+i,MIB,&got,0)||got!=MIB){err=GetLastError();goto end;}}if(!FlushFileBuffers(f)){err=GetLastError();goto end;}wt=GetTickCount64()-t;r=CreateFileW(path,0x80000000,7,0,3,0x28000080,0);if(r==BAD){err=GetLastError();goto end;}int64_t total=0;if(!GetFileSizeEx(r,&total)||total!=size){err=13;goto end;}t=GetTickCount64();for(U32 i=0;i<size;i+=MIB){U32 got=0;if(!ReadFile(r,readback,MIB,&got,0)||got!=MIB||memcmp(data+i,readback,MIB)){err=23;goto end;}}rt=GetTickCount64()-t;ok=wt&&rt;
end:if(r!=BAD)CloseHandle(r);if(f!=BAD)CloseHandle(f);if(readback)VirtualFree(readback,0,0x8000);if(data)VirtualFree(data,0,0x8000);if(!ok)return errnum(out,cap,L"검사를 마치지 못해 속도를 기록하지 않았습니다. 쓰기 권한·여유 공간을 확인하세요.",err);if(!route5(ep,route,CNT(route))){cp(out,cap,L"검사 중 VPN 경로가 바뀌어 속도 결과를 채택하지 않았습니다.");return 0;}U64 up=(U64)size*10/(wt*1000),dn=(U64)size*10/(rt*1000);_snwprintf(out,cap,L"256 MiB 저장 → 다시 열기 → 전체 바이트 일치\r\n쓰기 %u.%u MB/s  ·  읽기 %u.%u MB/s\r\n%ls. 외부망 여부는 시험 장소에서 확인하세요.",(U32)(up/10),(U32)(up%10),(U32)(dn/10),(U32)(dn%10),route);return 1;}
